import React, { useState } from 'react';
import { Pressable, Text, View } from 'react-native';
import notices from '../../lib/notices.json';
import { fonts, makeStyles, space } from '../../theme';

// Audit C-54: the open-source notices ship with the app. Generated by
// scripts/notices.js (regenerate after any dependency change). Nothing here
// goes online.

type Item = { n: string; v: string; l: string; t: number };
type Section = { title: string; note?: string; items: Item[] };
const SECTIONS = notices.sections as Section[];
const TEXTS = notices.texts as string[];

function Row({ item, last }: { item: Item; last: boolean }) {
  const styles = useStyles();
  const [open, setOpen] = useState(false);
  const hasText = item.t >= 0;
  return (
    <View style={[styles.row, !last && styles.divider]}>
      <Pressable
        accessibilityRole="button"
        accessibilityState={{ expanded: open }}
        disabled={!hasText}
        onPress={() => setOpen(o => !o)}
        style={({ pressed }) => [styles.head, pressed && styles.pressed]}
      >
        <Text style={styles.name}>
          {item.n} <Text style={styles.version}>{item.v}</Text>
        </Text>
        <Text style={styles.license}>
          {item.l}
          {hasText ? (open ? ' ‹' : ' ›') : ''}
        </Text>
      </Pressable>
      {open && hasText && (
        <Text style={styles.text} selectable>
          {TEXTS[item.t]}
        </Text>
      )}
    </View>
  );
}

export function AcknowledgementsPage() {
  const styles = useStyles();
  return (
    <>
      <Text style={styles.intro}>
        Zecky Lock it is built with the open-source software below. Tap a name
        to read its licence.
      </Text>
      {SECTIONS.map(section => (
        <View key={section.title}>
          <Text style={styles.section}>{section.title}</Text>
          <View style={styles.card}>
            {section.note != null && (
              <Text
                style={[
                  styles.note,
                  section.items.length > 0 && styles.divider,
                ]}
              >
                {section.note}
              </Text>
            )}
            {section.items.map((item, i) => (
              <Row
                key={`${item.n}@${item.v}`}
                item={item}
                last={i === section.items.length - 1}
              />
            ))}
          </View>
        </View>
      ))}
    </>
  );
}

const useStyles = makeStyles(colors => ({
  intro: {
    fontFamily: fonts.sans,
    fontSize: 13.5,
    lineHeight: 20,
    color: colors.textMuted,
    marginBottom: space.sm,
  },
  section: {
    fontFamily: fonts.sansSemiBold,
    fontSize: 11,
    letterSpacing: 1,
    textTransform: 'uppercase',
    color: colors.textMuted,
    marginTop: space.lg,
    marginBottom: space.xs,
  },
  card: {
    backgroundColor: colors.inkRaised,
    borderRadius: 16,
    borderWidth: 1,
    borderColor: colors.line,
    overflow: 'hidden',
  },
  divider: { borderBottomWidth: 0.5, borderBottomColor: colors.line },
  note: {
    fontFamily: fonts.sans,
    fontSize: 13,
    lineHeight: 19,
    color: colors.text,
    padding: space.md,
  },
  row: {},
  head: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 10,
    paddingHorizontal: space.md,
  },
  pressed: { opacity: 0.6 },
  name: {
    flex: 1,
    fontFamily: fonts.sansMedium,
    fontSize: 13.5,
    color: colors.text,
  },
  version: { fontFamily: fonts.sans, fontSize: 12, color: colors.textMuted },
  license: {
    fontFamily: fonts.sans,
    fontSize: 12,
    color: colors.goldDim,
    marginLeft: space.sm,
  },
  text: {
    fontFamily: fonts.sans,
    fontSize: 11,
    lineHeight: 16,
    color: colors.textMuted,
    paddingHorizontal: space.md,
    paddingBottom: space.md,
  },
}));
